theme_scss:
$enable-shadows: false;
$enable-gradients: false;
$enable-rounded: false;

// Bootstrap Variable Overrides
$font-family-sans-serif: 'Montserrat', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
$font-family-base: $font-family-sans-serif;
$primary: #FFBF00;
$body-bg: #ffffff;
$body-color: #171717;
$border-radius: 6px;
$border-radius-sm: 4px;
$border-radius-lg: 16px;


// Import themes from installed apps
@import "frappe/public/scss/website.bundle";
@import "erpnext/public/scss/website";
@import "dohw_intranet/public/scss/website";



// Custom Theme


:root {

	--border-radius-sm: 0px;
	--border-radius: 0px;
	--border-radius-md: 0px;
	--border-radius-lg: 0px;
	--border-radius-full: 0px;
	}
